import gurobipy as gp
from gurobipy import GRB

env = gp.Env(empty=True)
env.setParam('LogFile', 'model.log')
env.start()

model = gp.Model(env=env)

workshops = ['A', 'B', 'C', 'D']
components = [1, 2, 3]

x = {}
for w in workshops:
    for c in components:
        x[(w, c)] = model.addVar(name=f'x_{w}_{c}', lb=0)

P = model.addVar(name='P', lb=0)

capacities = {
    'A': 100,
    'B': 150,
    'C': 80,
    'D': 200
}

rates = {
    'A': [10, 15, 5],
    'B': [15, 10, 5],
    'C': [20, 5, 10],
    'D': [10, 15, 20]
}

for w in workshops:
    expr = 0
    for c in components:
        expr += x[(w, c)]
    model.addConstr(expr <= capacities[w], f'Capacity_{w}')

for c in components:
    expr = 0
    for w in workshops:
        expr += x[(w, c)] * rates[w][c-1]
    model.addConstr(expr >= P, f'Component_{c}')

model.setObjective(P, GRB.MAXIMIZE)

model.optimize()

if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
else:
    print("No optimal solution found.")
```

