model = gp.Model(env=env)

workshops = ['A', 'B', 'C', 'D']
components = [1, 2, 3]

x = {}
for i in workshops:
    for j in components:
        x[(i, j)] = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name=f"x_{i}_{j}")

z = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name="z")

capacity = {'A': 100, 'B': 150, 'C': 80, 'D': 200}
for i in workshops:
    model.addConstr(sum(x[(i, j)] for j in components) <= capacity[i], name=f"capacity_{i}")

rates = {
    'A': [10, 15, 5],
    'B': [15, 10, 5],
    'C': [20, 5, 10],
    'D': [10, 15, 20]
}
for j in components:
    expr = sum(rates[i][j-1] * x[(i, j)] for i in workshops)
    model.addConstr(expr >= z, name=f"component_{j}_constraint")

model.setObjective(z, GRB.MAXIMIZE)
model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
