import gurobipy as gp
from gurobipy import GRB

model = gp.Model(env=env)
x = {}
for i in range(1, 5):
    for j in range(1, 5):
        if i != j:
            x[(i, j)] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

for i in range(1, 5):
    model.addConstr(sum(x[(i, j)] for j in range(1, 5) if j != i) == 1, name=f"outgoing_{i}")
    model.addConstr(sum(x[(j, i)] for j in range(1, 5) if j != i) == 1, name=f"incoming_{i}")

distance = [
    [0, 10, 20, 12],
    [10, 0, 5, 10],
    [20, 5, 0, 8],
    [15, 12, 8, 0]
]
model.setObjective(sum(distance[i-1][j-1] * x[(i, j)] for i in range(1, 5) for j in range(1, 5) if i != j), GRB.MINIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
